// submitPaste sends the Enter that submits a landed paste, unless the host now
// says the pane's harness is gone.
//
// The liveness is read *after* the paste rather than only before it, because the
// window between the two commands is the one that matters: Claude exiting there
// leaves the operator's text sitting at a login shell prompt, and the Enter that
// would have submitted it to an assistant instead runs it as a command line in
// their working directory, unsandboxed. So a stopped pane gets Ctrl-U to discard
// the line and no Return at all.
//
// Only a liveness tmux is positive about withdraws. LivenessUnknown is a session
// that carries no recorded expectation and no row at all is a listing that did
// not mention it; neither is evidence the harness stopped, and refusing on either
// would withdraw working prompts from every session created before the option
// existed. A List that fails is not evidence either — it withdraws nothing, sends
// nothing, and returns, because a daemon that cannot ask the host must not type
// into it on a guess.
func (m *Manager) submitPaste(ctx context.Context, s Session) error {
	name := s.TmuxName()

	infos, err := m.tmux.List(ctx)
	if err != nil {
		return fmt.Errorf("check that session %s is still running: %w", s.ID, err)
	}
	for _, info := range infos {
		if info.Name != name || info.Claude != tmuxctl.LivenessStopped {
			continue
		}
		// The withdrawal is attempted and its failure is reported *beside* the
		// refusal rather than instead of it: whether or not the line could be
		// cleared, nothing was submitted and the caller's prompt did not land,
		// which is the fact the sentinel carries.
		notReady := fmt.Errorf("submit the prompt in session %s: %w", s.ID, ErrSessionNotReady)
		if err := m.tmux.SendKeys(ctx, name, clearLineKey); err != nil {
			return errors.Join(notReady, fmt.Errorf("withdraw the prompt in session %s: %w", s.ID, err))
		}
		return notReady
	}

	if err := m.tmux.SendKeys(ctx, name, enterKey); err != nil {
		return fmt.Errorf("submit the prompt in session %s: %w", s.ID, err)
	}
	return nil
}

