// TestPromptWithdrawsWhenClaudeExitsMidPrompt is the gap between the two
// commands Prompt sends. Claude can exit while the paste is in flight, and the
// pane behind it is then a login shell: the Enter that would have submitted the
// prompt instead runs the operator's text as a command line, unsandboxed, in
// their working directory. So the liveness is read again after the paste lands,
// a stopped pane gets C-u to clear what was pasted, and nothing is submitted.
//
// The error is the caller's answer rather than a logged warning, because a
// prompt that did not reach Claude must not be reported as delivered.
func TestPromptWithdrawsWhenClaudeExitsMidPrompt(t *testing.T) {
	t.Parallel()

	const payload = "run the tests"

	f := newManagerFixture(t)
	s, _ := mustCreate(t, f, f.request())
	f.tmux.ExitAfterPaste(s.TmuxName())
	before := len(f.tmux.Calls())

	err := f.mgr.Prompt(context.Background(), *s, payload)
	if !errors.Is(err, ErrSessionNotReady) {
		t.Fatalf("Prompt() error = %v; want one wrapping ErrSessionNotReady", err)
	}
	if strings.Contains(err.Error(), payload) {
		t.Errorf("Prompt() error carries the prompt text: %v", err)
	}

	got := f.tmux.Calls()[before:]
	want := []tmuxctl.Op{tmuxctl.OpPaste, tmuxctl.OpPaste, tmuxctl.OpList, tmuxctl.OpSendKeys}
	if !slices.Equal(opsOf(got), want) {
		t.Fatalf("Prompt() ran %v; want %v", opsOf(got), want)
	}
	if last := got[3].Argv[len(got[3].Argv)-1]; last != clearLineKey {
		t.Errorf("send-keys ends in %q; want %q", last, clearLineKey)
	}
	for _, c := range got {
		if slices.Contains(c.Argv, enterKey) {
			t.Errorf("a withdrawn prompt was submitted anyway: %s %q", c.Op, c.Argv)
		}
	}
}

